#nullable enable
using System.Collections.Immutable;
using HourBooking.Contracts;

namespace HourBooking.Slices.Booking;

/// <summary>
/// Live aggregation over the Timesheet stream, keyed by employeeId + month. Nothing registers a
/// projection for this: Marten folds it on demand when the endpoint asks.
///
/// Third slice on this stream, and the first one where the per-slice fold is genuinely SMALLER rather
/// than a copy. book-hours and correct-hours both need a day's arithmetic, so both carry a
/// <c>Line(date, projectId, hours)</c>. remove-booking has exactly one state question — "is there a
/// booking still standing under this id?" — so the smallest honest fold is a set of ids. Folding date
/// and hours here would be state nothing reads, which is how a fold quietly becomes "the" aggregate.
///
/// Folds every event of the stream, not only this slice's: BookingRemoved is what takes an id back
/// out, and it is emitted by this very slice, so a fold that ignored it would let the same booking be
/// removed twice.
///
/// The model draws HoursBooked first in this stream, but there is deliberately no Create method: a
/// no-arg constructor lets any event open the stream. ZeroHoursFilled can be first. See
/// ANTI-PATTERNS.md #1.
/// </summary>
public sealed record RemoveBookingState
{
    public string Id { get; init; } = default!;

    /// <summary>Marten's convention. The aggregate workflow uses it for optimistic concurrency.</summary>
    public int Version { get; set; }

    /// <summary>
    /// The bookings still standing in this (employee, month), by id. A set rather than a dictionary of
    /// lines because presence is the whole question this slice asks.
    /// </summary>
    public ImmutableHashSet<Guid> Standing { get; init; } = ImmutableHashSet<Guid>.Empty;

    public static string StreamKey(Guid employeeId, string month)
        => $"timesheet:{employeeId}:{month}";

    // --- what the endpoint asks it ---------------------------------------------------------------

    /// <summary>
    /// "A booking already removed cannot be removed again." Also answers "a booking that never
    /// existed", which is the same refusal — BookingNotFound — because from the stream's point of view
    /// the two are indistinguishable, and telling them apart would leak whether an id ever existed.
    /// </summary>
    public bool IsStanding(Guid bookingId) => Standing.Contains(bookingId);

    // --- the fold --------------------------------------------------------------------------------

    public static RemoveBookingState Apply(HoursBooked e, RemoveBookingState current) =>
        current with { Standing = current.Standing.Add(e.BookingId) };

    /// <summary>
    /// A correction changes a standing booking's hours and nothing else — it can neither create a
    /// booking nor take one back ("a correction cannot take the hours to zero; removal is the only
    /// way"). So it moves this fold not at all, and saying so is the point of the method.
    /// </summary>
    public static RemoveBookingState Apply(HoursCorrected e, RemoveBookingState current) => current;

    public static RemoveBookingState Apply(BookingRemoved e, RemoveBookingState current) =>
        current with { Standing = current.Standing.Remove(e.BookingId) };

    /// <summary>A zero-filled day is a standing booking like any other, so it can be removed.</summary>
    public static RemoveBookingState Apply(ZeroHoursFilled e, RemoveBookingState current) =>
        current with { Standing = current.Standing.Add(e.BookingId) };
}
